         + texture(g_Texture0, uv + stp) * 0.156756
         + texture(g_Texture0, uv + stp * 2.0) * 0.119007
         + texture(g_Texture0, uv + stp * 3.0) * 0.075189
         + texture(g_Texture0, uv + stp * 4.0) * 0.039533
         + texture(g_Texture0, uv + stp * 5.0) * 0.017298
